-- 124_fill_italian_titles.sql
-- Fills documents.it_title from what the archive already holds. No translation here, and only empty it_title fields are written:
-- no other field changes and no existing Italian title is overwritten. Generated by Documentazione/titoli-italiani/costruisci.mjs.
-- In order, each one only where the step before left it empty:
--   italian_version  the original_title of an Italian version
--   original_title   the original_title of an old Urdu record: Italian in the 377 such records read on 2026-11-06. Not from a proposal,
--                    where it holds the version's own language, and not when it only repeats the English title
--   hayat            the Italian title in the Hayat index, when no version of the Work has one yet
--   heading          the Italian heading at the top of the text, read and cleaned by hand, when no version of the Work has one yet
--   other_version    another version of the same Work, when the Work has only one Italian title, never taken from a reserved document
-- Run it in the SQL Editor. It can be run twice. What it wrote is kept in a table, and undone like this:
--   update public.documents d set it_title = null from public._filled_it_title_20261106 f where d.document_id = f.document_id and d.it_title = f.it_title;

create table if not exists public._filled_it_title_20261106 (
  document_id integer primary key,
  it_title    text not null,
  source      text not null,
  filled_at   timestamptz not null default now()
);
alter table public._filled_it_title_20261106 enable row level security;

with done as (
  update public.documents d
  set it_title = regexp_replace(btrim(d.original_title), '\s+', ' ', 'g')
  where nullif(btrim(d.it_title), '') is null
    and d.deleted_at is null
    and d.language = 'ITA'
    and nullif(btrim(d.original_title), '') is not null
    and d.original_title !~ '[\u0600-\u06FF]'
  returning d.document_id, d.it_title
)
insert into public._filled_it_title_20261106 (document_id, it_title, source)
select document_id, it_title, 'italian_version' from done
on conflict (document_id) do nothing;

with done as (
  update public.documents d
  set it_title = regexp_replace(btrim(d.original_title), '\s+', ' ', 'g')
  where nullif(btrim(d.it_title), '') is null
    and d.deleted_at is null
    and d.language = 'URD'
    and d.source_submission_id is null
    and nullif(btrim(d.original_title), '') is not null
    and d.original_title !~ '[\u0600-\u06FF]'
    and lower(btrim(d.original_title)) is distinct from lower(btrim(d.en_title))
    and lower(btrim(d.original_title)) is distinct from lower(btrim(d.title))
  returning d.document_id, d.it_title
)
insert into public._filled_it_title_20261106 (document_id, it_title, source)
select document_id, it_title, 'original_title' from done
on conflict (document_id) do nothing;

with done as (
  update public.documents d
  set it_title = regexp_replace(btrim(h.titolo), '\s+', ' ', 'g')
  from public.hayat_indice h
  where h.id = d.hayat_index_ref
    and nullif(btrim(d.it_title), '') is null
    and d.deleted_at is null
    and nullif(btrim(h.titolo), '') is not null
    and h.titolo !~ '[\u0600-\u06FF]'
    and lower(btrim(h.titolo)) is distinct from lower(btrim(d.en_title))
    and lower(btrim(h.titolo)) is distinct from lower(btrim(d.title))
    and not exists (select 1 from public.documents o
                    where o.work_id = d.work_id and nullif(btrim(o.it_title), '') is not null)
  returning d.document_id, d.it_title
)
insert into public._filled_it_title_20261106 (document_id, it_title, source)
select document_id, it_title, 'hayat' from done
on conflict (document_id) do nothing;

