with one_title as (
  select o.work_id, min(btrim(o.it_title)) as it_title
  from public.documents o
  where o.work_id is not null
    and nullif(btrim(o.it_title), '') is not null
    and o.deleted_at is null
    and o.access_level <> 'reserved'
  group by o.work_id
  having count(distinct lower(btrim(o.it_title))) = 1
), done as (
  update public.documents d
  set it_title = w.it_title
  from one_title w
  where w.work_id = d.work_id
    and nullif(btrim(d.it_title), '') is null
    and d.deleted_at is null
  returning d.document_id, d.it_title
)
insert into public._filled_it_title_20261106 (document_id, it_title, source)
select document_id, it_title, 'other_version' from done
on conflict (document_id) do nothing;

-- Verification (the SQL Editor shows only the last result).
-- The first five rows are documents filled from each source. The others count Works: works_without_italian is what is left to translate,
-- works_with_several_titles have versions with different Italian titles and were left as they are, for a person to look at.
with o as (
  select coalesce('w' || d.work_id::text, 'd' || d.document_id::text) as opera,
         count(distinct lower(btrim(d.it_title))) as titoli
  from public.documents d
  where d.deleted_at is null
  group by 1
)
select ord, what, n from (
  select 1 as ord, 'filled: italian_version' as what, count(*) as n from public._filled_it_title_20261106 where source = 'italian_version'
  union all select 2, 'filled: original_title', count(*) from public._filled_it_title_20261106 where source = 'original_title'
  union all select 3, 'filled: hayat', count(*) from public._filled_it_title_20261106 where source = 'hayat'
  union all select 4, 'filled: heading', count(*) from public._filled_it_title_20261106 where source = 'heading'
  union all select 5, 'filled: other_version', count(*) from public._filled_it_title_20261106 where source = 'other_version'
  union all select 6, 'works', count(*) from o
  union all select 7, 'works_with_italian', count(*) from o where titoli > 0
  union all select 8, 'works_without_italian', count(*) from o where titoli = 0
  union all select 9, 'works_with_several_titles', count(*) from o where titoli > 1
) r
order by ord;
